  84	/** Deterministic permutation, different at every step. */
  85	const permute = <T>(items: T[], seed: number): T[] => {
  86	  const copy = [...items];
  87	  let state = seed;
  88	  for (let index = copy.length - 1; index > 0; index -= 1) {
  89	    state = (state * 1103515245 + 12345) % 2147483648;
  90	    const swap = state % (index + 1);
  91	    [copy[index], copy[swap]] = [copy[swap]!, copy[index]!];
  92	  }
  93	  return copy;
